-- Accounting export is controlled by a locked headquarters period, while the
-- immutable source journals retain their child branch period provenance.

create or replace function finance_api.commit_accounting_batch_creation(p_actor_id uuid,p_legal_entity_id uuid,p_period_start date,p_period_end date,p_mapping_version text,p_journal_entry_ids uuid[],p_idempotency_key text,p_intent_hash text,p_correlation_id uuid)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare v_period finance.finance_periods%rowtype;v_existing finance.accounting_batches%rowtype;v_entry record;v_entry_id uuid;v_batch_id uuid;v_package_id uuid;v_currency text;v_debit numeric(24,8):=0;v_credit numeric(24,8):=0;v_count integer:=0;v_package_count integer:=0;v_entry_hash text;v_member_material text:='';v_content_hash text;v_payload jsonb;v_payload_hash text;v_previous_hash text;v_audit_hash text;
begin
 if not finance_private.current_accounting_batch_worker_is_trusted() then raise exception using errcode='42501',message='accounting batch worker denied';end if;
 if p_actor_id is null or p_legal_entity_id is null or p_period_start is null or p_period_end is null or p_period_start>p_period_end or coalesce(pg_catalog.btrim(p_mapping_version),'')='' or pg_catalog.length(p_mapping_version)>100 or coalesce(pg_catalog.btrim(p_idempotency_key),'')='' or pg_catalog.length(p_idempotency_key)>200 or p_intent_hash!~'^[a-fA-F0-9]{64}$' or p_correlation_id is null then raise exception using errcode='22023',message='required accounting batch fields missing';end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('accounting-batch:'||p_legal_entity_id::text||':'||p_period_start::text||':'||p_period_end::text,0));
 select * into v_existing from finance.accounting_batches b where b.legal_entity_id=p_legal_entity_id and b.idempotency_key=p_idempotency_key for update;
 if found then if v_existing.intent_hash=p_intent_hash then return pg_catalog.jsonb_build_object('outcome','REPLAY','batchId',v_existing.id,'status',v_existing.status,'contentHash',v_existing.content_hash,'entryCount',(select count(*) from finance.accounting_batch_entries e where e.accounting_batch_id=v_existing.id and e.status='ACTIVE'),'debitTotal',v_existing.debit_total::text,'creditTotal',v_existing.credit_total::text,'currencyCode',v_existing.currency_code,'version',v_existing.version);end if;return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 select * into v_period from finance.finance_periods fp where fp.legal_entity_id=p_legal_entity_id and fp.scope_type='HEADQUARTERS' and fp.mode='LIVE' and fp.status='LOCKED' and fp.period_start=p_period_start and fp.period_end=p_period_end;
 if not found then raise exception using errcode='23514',message='locked live headquarters finance period required';end if;
 for v_entry_id in select je.id from finance.journal_entries je join finance.finance_periods ep on ep.id=je.finance_period_id where je.legal_entity_id=p_legal_entity_id and (ep.id=v_period.id or ep.parent_period_id=v_period.id) and je.status='POSTED' and (coalesce(pg_catalog.cardinality(p_journal_entry_ids),0)=0 or je.id=any(p_journal_entry_ids)) order by je.id for update of je
 loop
  select je.id,je.posting_date,pg_catalog.min(jl.currency_code) currency_code,pg_catalog.sum(jl.debit_amount) debit_total,pg_catalog.sum(jl.credit_amount) credit_total,pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('lineNo',jl.line_no,'accountCode',jl.account_code,'dealerAccountId',jl.dealer_account_id,'branchId',jl.branch_id,'currency',jl.currency_code,'debit',jl.debit_amount::text,'credit',jl.credit_amount::text) order by jl.line_no) lines into strict v_entry from finance.journal_entries je join finance.journal_lines jl on jl.journal_entry_id=je.id where je.id=v_entry_id group by je.id,je.posting_date;
  if v_entry.debit_total<>v_entry.credit_total or v_entry.debit_total<=0 then raise exception using errcode='23514',message='balanced posted journal entry required';end if;
  if exists(select 1 from finance.journal_lines jl where jl.journal_entry_id=v_entry.id and jl.currency_code<>v_entry.currency_code) then raise exception using errcode='23514',message='single currency journal entry required';end if;
  if exists(select 1 from finance.journal_lines jl where jl.journal_entry_id=v_entry.id and (jl.dealer_account_id is null or jl.branch_id is null)) or (select count(distinct jl.dealer_account_id::text||':'||jl.branch_id::text) from finance.journal_lines jl where jl.journal_entry_id=v_entry.id)<>1 then raise exception using errcode='23514',message='single dealer and branch accounting package scope required';end if;
  if v_currency is null then v_currency:=v_entry.currency_code;elsif v_currency<>v_entry.currency_code then raise exception using errcode='23514',message='single currency accounting batch required';end if;
  if not finance_private.accounting_export_mapping_is_valid(p_legal_entity_id,p_mapping_version,v_entry.id) then raise exception using errcode='23514',message='approved accounting export mapping required';end if;
  if exists(select 1 from finance.accounting_batch_entries abe where abe.journal_entry_id=v_entry.id and abe.status='ACTIVE') then return pg_catalog.jsonb_build_object('outcome','CONFLICT','journalEntryId',v_entry.id);end if;
  v_entry_hash:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(v_entry.id::text||':'||v_entry.lines::text,'UTF8'),'sha256'),'hex');v_member_material:=v_member_material||':'||v_entry.id::text||':'||v_entry_hash;v_count:=v_count+1;v_debit:=v_debit+v_entry.debit_total;v_credit:=v_credit+v_entry.credit_total;
 end loop;
 if v_count=0 then raise exception using errcode='23514',message='eligible posted journal entry required';end if;
 if coalesce(pg_catalog.cardinality(p_journal_entry_ids),0)>0 and v_count<>pg_catalog.cardinality(p_journal_entry_ids) then raise exception using errcode='23514',message='requested journal entry set incomplete';end if;
 if v_debit<>v_credit then raise exception using errcode='23514',message='accounting batch is not balanced';end if;
 v_content_hash:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(p_legal_entity_id::text||':'||v_period.id::text||':'||p_mapping_version||':'||v_currency||':'||v_debit::text||':'||v_credit::text||v_member_material,'UTF8'),'sha256'),'hex');
 insert into finance.accounting_batches(legal_entity_id,finance_period_id,idempotency_key,intent_hash,batch_no,mapping_version,currency_code,debit_total,credit_total,content_hash,status,created_by,correlation_id) values(p_legal_entity_id,v_period.id,p_idempotency_key,p_intent_hash,'ACC-'||pg_catalog.to_char(p_period_end,'YYYYMMDD')||'-'||pg_catalog.substr(v_content_hash,1,12),p_mapping_version,v_currency,v_debit,v_credit,v_content_hash,'READY',p_actor_id,p_correlation_id) returning id into v_batch_id;
 insert into finance.accounting_batch_packages(accounting_batch_id,dealer_account_id,branch_id,package_order,debit_total,credit_total,content_hash,status,created_by,correlation_id)
 select v_batch_id,s.dealer_account_id,s.branch_id,pg_catalog.row_number() over(order by s.dealer_account_id,s.branch_id),s.debit_total,s.credit_total,pg_catalog.encode(extensions.digest(pg_catalog.convert_to(v_batch_id::text||':'||s.dealer_account_id::text||':'||s.branch_id::text||':'||s.debit_total::text||':'||s.credit_total::text||':'||s.entry_ids,'UTF8'),'sha256'),'hex'),'READY',p_actor_id,p_correlation_id
 from (select pg_catalog.min(jl.dealer_account_id::text)::uuid dealer_account_id,pg_catalog.min(jl.branch_id::text)::uuid branch_id,pg_catalog.sum(jl.debit_amount) debit_total,pg_catalog.sum(jl.credit_amount) credit_total,pg_catalog.string_agg(distinct je.id::text,',' order by je.id::text) entry_ids from finance.journal_entries je join finance.finance_periods ep on ep.id=je.finance_period_id join finance.journal_lines jl on jl.journal_entry_id=je.id where je.legal_entity_id=p_legal_entity_id and (ep.id=v_period.id or ep.parent_period_id=v_period.id) and je.status='POSTED' and (coalesce(pg_catalog.cardinality(p_journal_entry_ids),0)=0 or je.id=any(p_journal_entry_ids)) group by jl.dealer_account_id,jl.branch_id) s;
 get diagnostics v_package_count=row_count;if v_package_count<1 then raise exception using errcode='23514',message='accounting package required';end if;
 for v_entry in select je.id,pg_catalog.min(jl.dealer_account_id::text)::uuid dealer_account_id,pg_catalog.min(jl.branch_id::text)::uuid branch_id,pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('lineNo',jl.line_no,'accountCode',jl.account_code,'dealerAccountId',jl.dealer_account_id,'branchId',jl.branch_id,'currency',jl.currency_code,'debit',jl.debit_amount::text,'credit',jl.credit_amount::text) order by jl.line_no) lines from finance.journal_entries je join finance.finance_periods ep on ep.id=je.finance_period_id join finance.journal_lines jl on jl.journal_entry_id=je.id where je.legal_entity_id=p_legal_entity_id and (ep.id=v_period.id or ep.parent_period_id=v_period.id) and je.status='POSTED' and (coalesce(pg_catalog.cardinality(p_journal_entry_ids),0)=0 or je.id=any(p_journal_entry_ids)) group by je.id order by je.id
 loop v_entry_hash:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(v_entry.id::text||':'||v_entry.lines::text,'UTF8'),'sha256'),'hex');select p.id into strict v_package_id from finance.accounting_batch_packages p where p.accounting_batch_id=v_batch_id and p.dealer_account_id=v_entry.dealer_account_id and p.branch_id=v_entry.branch_id;insert into finance.accounting_batch_entries(accounting_batch_id,accounting_batch_package_id,journal_entry_id,entry_order,snapshot_hash,status,created_by,correlation_id) values(v_batch_id,v_package_id,v_entry.id,(select count(*)+1 from finance.accounting_batch_entries x where x.accounting_batch_id=v_batch_id),v_entry_hash,'ACTIVE',p_actor_id,p_correlation_id);end loop;
 v_payload:=pg_catalog.jsonb_build_object('batchId',v_batch_id,'legalEntityId',p_legal_entity_id,'financePeriodId',v_period.id,'mappingVersion',p_mapping_version,'currencyCode',v_currency,'debitTotal',v_debit::text,'creditTotal',v_credit::text,'entryCount',v_count,'packageCount',v_package_count,'contentHash',v_content_hash,'intentHash',p_intent_hash);v_payload_hash:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(v_payload::text,'UTF8'),'sha256'),'hex');insert into finance.outbox_messages(legal_entity_id,topic,event_type,aggregate_type,aggregate_id,aggregate_version,payload,payload_hash,status,correlation_id) values(p_legal_entity_id,'finance.accounting','ACCOUNTING_BATCH_READY','accounting_batch',v_batch_id,1,v_payload,v_payload_hash,'PENDING',p_correlation_id);
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('audit:'||p_legal_entity_id::text,0));select ae.integrity_hash into v_previous_hash from finance.audit_events ae where ae.legal_entity_id=p_legal_entity_id order by ae.created_at_utc desc,ae.id desc limit 1;v_audit_hash:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(coalesce(v_previous_hash,'GENESIS')||':'||v_batch_id::text||':ACCOUNTING_BATCH_READY:'||p_intent_hash||':'||p_correlation_id::text,'UTF8'),'sha256'),'hex');insert into finance.audit_events(legal_entity_id,actor_id,actor_type,action_code,subject_type,subject_id,decision,after_hash,previous_integrity_hash,integrity_hash,safe_context,correlation_id) values(p_legal_entity_id,p_actor_id,'USER','ACCOUNTING_BATCH_READY','accounting_batch',v_batch_id,'ALLOW',v_content_hash,v_previous_hash,v_audit_hash,pg_catalog.jsonb_build_object('financePeriodId',v_period.id,'mappingVersion',p_mapping_version,'entryCount',v_count,'currencyCode',v_currency,'debitTotal',v_debit::text,'creditTotal',v_credit::text),p_correlation_id);
 return pg_catalog.jsonb_build_object('outcome','CREATED','batchId',v_batch_id,'status','READY','contentHash',v_content_hash,'entryCount',v_count,'debitTotal',v_debit::text,'creditTotal',v_credit::text,'currencyCode',v_currency,'version',1);
end $$;

revoke all on function finance_api.commit_accounting_batch_creation(uuid,uuid,date,date,text,uuid[],text,text,uuid) from public,anon,authenticated;
grant execute on function finance_api.commit_accounting_batch_creation(uuid,uuid,date,date,text,uuid[],text,text,uuid) to service_role;
